parameters.jsCode:
const req = $('Webhook').first().json.body || $('Webhook').first().json;
const centerCode = (req.center_code || '').trim().toUpperCase();
const reportDate = (req.report_date || '').trim();

const allRows = $input.all();
const baoCaoItems = [];

for (const it of allRows) {
  const row = it.json;
  const rowCenter = String(row['Mã TTBH'] || '').trim().toUpperCase();
  const rowDate = String(row['Ngày báo cáo'] || '').trim();

  // Chỉ lấy đúng center_code và report_date
  if (rowCenter !== centerCode) continue;
  if (rowDate !== reportDate) continue;

  const isTgdd = row['Khách hàng'] === 'TGDĐ';

  // Quy chuẩn đối với TGDĐ vs KL:
  // - Đối với TGDĐ: công nợ điền số 0 (nếu k phát sinh hoặc BH), tiền mặt để trống (không dùng tiền mặt)
  // - Đối với KL: công nợ để trống (không tính KL trong công nợ), tiền mặt điền số tiền thực thu
  let debtVal = '';
  let cashVal = '';

  if (isTgdd) {
    debtVal = (row['Công nợ'] !== null && row['Công nợ'] !== undefined) ? parseFloat(row['Công nợ']) : 0;
    cashVal = '';
  } else {
    debtVal = '';
    cashVal = (row['Doanh thu tiền mặt'] !== null && row['Doanh thu tiền mặt'] !== undefined) ? parseFloat(row['Doanh thu tiền mặt']) : 0;
  }

  // Giữ đúng 10 cột cho tab BaoCao
  baoCaoItems.push({
    json: {
      'Số phiếu sửa chữa': row['Số phiếu sửa chữa'] || '',
      'Mã vật tư linh kiện': row['Mã vật tư linh kiện'] || '',
      'Tên vật tư': row['Tên vật tư'] || '',
      'Đơn giá': row['Đơn giá'] !== null && row['Đơn giá'] !== undefined ? parseFloat(row['Đơn giá']) : null,
      'Doanh thu tiền mặt': cashVal,
      'Công nợ': debtVal,
      'Khách hàng': row['Khách hàng'] || '',
      'Phương thức thanh toán': row['Phương thức thanh toán'] || '',
      'Xuất Bảo Hành': (row['Xuất Bảo Hành'] === 1 || row['Xuất Bảo Hành'] === '1') ? 1 : '',
      'Xuất Sửa Chữa': (row['Xuất Sửa Chữa'] === 1 || row['Xuất Sửa Chữa'] === '1') ? 1 : ''
    }
  });
}

return baoCaoItems;

